package main

import (
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
)

// generatedMarker is the text every generated file carries on its first line.
// It follows the Go convention ("Code generated ... DO NOT EDIT.") so tools
// recognise the file, and it is how --check tells generated files from
// hand-written ones that live in the same directories.
const generatedMarker = "Code generated by tools/schemagen"

// goFile accumulates the body and the imports of one generated Go file.
type goFile struct {
	area    string
	module  string // import path prefix of the generated packages
	imports map[string]bool
	body    strings.Builder
}

func newGoFile(area, module string) *goFile {
	return &goFile{area: area, module: module, imports: map[string]bool{}}
}

func (g *goFile) use(path string) { g.imports[path] = true }

func (g *goFile) w(format string, args ...any) { fmt.Fprintf(&g.body, format, args...) }

// ref spells a declaration as seen from this file's package, importing the
// package it lives in when that is another area.
func (g *goFile) ref(d *Decl) string {
	if d.File.Area == g.area {
		return d.Name
	}
	g.use(g.module + "/" + goPkgName(d.File.Area))
	return goPkgName(d.File.Area) + "." + d.Name
}

// typeExpr renders a use-site type.
func (g *goFile) typeExpr(t *Type) string {
	switch t.Kind {
	case tString:
		return "string"
	case tInteger:
		return "int64"
	case tNumber:
		return "float64"
	case tBool:
		return "bool"
	case tNull, tAny, tLoose:
		return "any"
	case tObjectAny:
		return "map[string]any"
	case tConst:
		return g.typeExpr(&Type{Kind: t.Const.Kind})
	case tArray:
		return "[]" + g.typeExpr(t.Elem)
	case tMap:
		return "map[string]" + g.typeExpr(t.Elem)
	case tNullable:
		inner := g.typeExpr(t.Elem)
		if goNilable(t.Elem) {
			return inner
		}
		return "*" + inner
	case tNamed:
		return g.ref(t.Decl)
	}
	panic("schemagen: unknown type kind")
}

// goNilable reports whether the Go form of t already has a nil value, so
// "nullable" and "optional" need no extra pointer.
func goNilable(t *Type) bool {
	switch t.Kind {
	case tNull, tAny, tLoose, tObjectAny, tArray, tMap, tNullable:
		return true
	case tNamed:
		switch t.Decl.Kind {
		case dAlias, dDefined:
			return t.Decl.Under != nil && goNilable(t.Decl.Under)
		}
	}
	return false
}

// goComment renders doc lines as a // comment block.
func goComment(indent string, lines []string) string {
	var b strings.Builder
	for _, l := range lines {
		if l == "" {
			b.WriteString(indent + "//\n")
		} else {
			b.WriteString(indent + "// " + l + "\n")
		}
	}
	return b.String()
}

// docLines wraps each paragraph and separates paragraphs with a blank line.
func docLines(width int, paras ...string) []string {
	var out []string
	for _, p := range paras {
		w := wrapText(p, width)
		if len(w) == 0 {
			continue
		}
		if len(out) > 0 {
			out = append(out, "")
		}
		out = append(out, w...)
	}
	return out
}

// declDoc is the documentation of a declaration, shared by Go and TypeScript.
func declDoc(d *Decl, width int) []string {
	paras := []string{d.Name + " mirrors " + d.schemaRef() + "."}
	if d.Doc != "" {
		paras = append(paras, d.Doc)
	}
	if d.Constraints != "" {
		paras = append(paras, d.Constraints)
	}
	switch d.Kind {
	case dStruct:
		if d.Overlay {
			paras = append(paras, "The schema also states cross-field rules (if/then/else, required alternatives and similar) that this type does not express: validate payloads against the schema.")
		}
	case dEnum:
		paras = append(paras, "Only the values listed in the schema are valid.")
	case dUnion:
		var names []string
		for _, v := range d.Variants {
			names = append(names, v.Decl.Name)
		}
		paras = append(paras, "It is a union discriminated by the "+strconv.Quote(d.Disc)+" property: exactly one of "+strings.Join(names, ", ")+".")
	}
	return docLines(width, paras...)
}

// emitGoDecl renders one declaration.
func emitGoDecl(g *goFile, d *Decl) {
	g.w("%s", goComment("", declDoc(d, 96)))
	switch d.Kind {
	case dStruct:
		emitGoStruct(g, d)
	case dEnum:
		emitGoEnum(g, d)
	case dUnion:
		emitGoUnion(g, d)
	case dDefined:
		g.w("type %s %s\n\n", d.Name, g.typeExpr(d.Under))
	case dAlias:
		g.w("type %s = %s\n\n", d.Name, g.typeExpr(d.Under))
	}
}

func emitGoStruct(g *goFile, d *Decl) {
	g.w("type %s struct {\n", d.Name)
	for i, f := range d.Fields {
		if i > 0 {
			g.w("\n")
		}
		doc := docLines(88, f.Doc)
		if f.Authority != "" {
			if len(doc) > 0 {
				doc = append(doc, "")
			}
			doc = append(doc, "Authority: "+f.Authority+".")
		}
		g.w("%s", goComment("\t", doc))
		typ := g.typeExpr(f.Type)
		opt := ""
		if !f.Required {
			opt = ",omitzero"
			if !goNilable(f.Type) {
				typ = "*" + typ
			}
		}
		tag := "json:" + strconv.Quote(f.JSON+opt)
		if f.Authority != "" {
			tag += " alixai:" + strconv.Quote(f.Authority)
		}
		g.w("\t%s %s `%s`\n", f.GoName, typ, tag)
	}
	g.w("}\n\n")

	// MarshalJSON forces const members to their schema value and keeps
	// required arrays and maps from encoding as null.
	var stmts []string
	for _, f := range d.Fields {
		if !f.Required {
			continue
		}
		switch {
		case f.Type.Kind == tConst:
			stmts = append(stmts, fmt.Sprintf("a.%s = %s", f.GoName, goConstLiteral(f.Type.Const)))
		case isSliceOrMap(f.Type):
			stmts = append(stmts, fmt.Sprintf("if a.%s == nil {\n\t\ta.%s = %s{}\n\t}", f.GoName, f.GoName, g.typeExpr(f.Type)))
		}
	}
	if len(stmts) == 0 {
		return
	}
	g.use("encoding/json")
	g.w("// MarshalJSON encodes the value with its const members forced to the value the\n")
	g.w("// schema fixes and with required arrays and maps never null.\n")
	g.w("func (v %s) MarshalJSON() ([]byte, error) {\n", d.Name)
	g.w("\ttype plain %s\n", d.Name)
	g.w("\ta := plain(v)\n")
	for _, s := range stmts {
		g.w("\t%s\n", s)
	}
	g.w("\treturn json.Marshal(a)\n")
	g.w("}\n\n")
}

// isSliceOrMap reports whether t is a required, non-nullable slice or map in Go.
func isSliceOrMap(t *Type) bool {
	switch t.Kind {
	case tArray, tMap:
		return true
	case tNamed:
		return t.Decl.Kind == dDefined && t.Decl.Under != nil && isSliceOrMap(t.Decl.Under)
	}
	return false
}

func goConstLiteral(c *Const) string {
	switch c.Kind {
	case tString:
		return strconv.Quote(c.Str)
	case tBool:
		return strconv.FormatBool(c.Bool)
	}
	return c.Num
}

func emitGoEnum(g *goFile, d *Decl) {
	g.use("bytes")
	g.use("encoding/json")
	g.use("fmt")
	base := "string"
	lit := func(ev EnumValue) string { return strconv.Quote(ev.Raw) }
	if d.EnumKind == tInteger {
		base = "int64"
		lit = func(ev EnumValue) string { return ev.Raw }
	}
	g.w("type %s %s\n\n", d.Name, base)
	g.w("// The valid values of %s.\n", d.Name)
	g.w("const (\n")
	for _, ev := range d.Values {
		g.w("\t%s %s = %s\n", ev.Name, d.Name, lit(ev))
	}
	g.w(")\n\n")

	names := make([]string, len(d.Values))
	for i, ev := range d.Values {
		names[i] = ev.Name
	}
	g.w("// Valid reports whether v is one of the values the schema lists.\n")
	g.w("func (v %s) Valid() bool {\n\tswitch v {\n\tcase %s:\n\t\treturn true\n\t}\n\treturn false\n}\n\n", d.Name, strings.Join(names, ", "))

	g.w("// MarshalJSON refuses to encode a value outside the enum, so an unset or\n")
	g.w("// corrupt value fails instead of producing a document the schema rejects.\n")
	g.w("func (v %s) MarshalJSON() ([]byte, error) {\n", d.Name)
	g.w("\tif !v.Valid() {\n\t\treturn nil, fmt.Errorf(\"%s: %%v is not a valid value\", %s(v))\n\t}\n", d.Name, base)
	g.w("\treturn json.Marshal(%s(v))\n}\n\n", base)

	g.w("// UnmarshalJSON accepts only the values the schema lists; null and anything\n")
	g.w("// else is an error.\n")
	g.w("func (v *%s) UnmarshalJSON(data []byte) error {\n", d.Name)
	g.w("\tif bytes.Equal(bytes.TrimSpace(data), []byte(\"null\")) {\n\t\treturn fmt.Errorf(\"%s: null is not a valid value\")\n\t}\n", d.Name)
	g.w("\tvar raw %s\n", base)
	g.w("\tif err := json.Unmarshal(data, &raw); err != nil {\n\t\treturn fmt.Errorf(\"%s: %%w\", err)\n\t}\n", d.Name)
	g.w("\tif !%s(raw).Valid() {\n\t\treturn fmt.Errorf(\"%s: %%v is not a valid value\", raw)\n\t}\n", d.Name, d.Name)
	g.w("\t*v = %s(raw)\n\treturn nil\n}\n\n", d.Name)
}

func emitGoUnion(g *goFile, d *Decl) {
	g.use("encoding/json")
	g.use("fmt")
	iface := d.Name + "Value"
	marker := "is" + d.Name
	var names []string
	for _, v := range d.Variants {
		names = append(names, v.Decl.Name)
	}
	g.w("type %s struct {\n", d.Name)
	g.w("%s", goComment("\t", docLines(88, "Value holds the variant: one of "+strings.Join(names, ", ")+". The zero value holds none and cannot be encoded.")))
	g.w("\tValue %s\n", iface)
	g.w("}\n\n")
	g.w("// %s is implemented by every variant of %s and by nothing else.\n", iface, d.Name)
	g.w("type %s interface {\n\t%s()\n}\n\n", iface, marker)
	for _, v := range d.Variants {
		g.w("func (%s) %s() {}\n", v.Decl.Name, marker)
	}
	g.w("\n")

	g.w("// MarshalJSON encodes the variant that is set. The discriminator is written by\n")
	g.w("// the variant itself, so it can never disagree with the variant's type.\n")
	g.w("func (u %s) MarshalJSON() ([]byte, error) {\n", d.Name)
	g.w("\tif u.Value == nil {\n\t\treturn nil, fmt.Errorf(\"%s: no variant set\")\n\t}\n", d.Name)
	g.w("\tb, err := json.Marshal(u.Value)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n")
	g.w("\tif string(b) == \"null\" {\n\t\treturn nil, fmt.Errorf(\"%s: nil variant\")\n\t}\n", d.Name)
	g.w("\treturn b, nil\n}\n\n")

	g.w("// UnmarshalJSON reads the discriminator and decodes the matching variant\n")
	g.w("// strictly (unknown members are errors). A missing or unknown discriminator\n")
	g.w("// is an error: nothing is guessed.\n")
	g.w("func (u *%s) UnmarshalJSON(data []byte) error {\n", d.Name)
	g.w("\tvar probe struct {\n\t\tDisc *string `json:%s`\n\t}\n", strconv.Quote(d.Disc))
	g.w("\tif err := json.Unmarshal(data, &probe); err != nil {\n\t\treturn fmt.Errorf(\"%s: %%w\", err)\n\t}\n", d.Name)
	g.w("\tif probe.Disc == nil {\n\t\treturn fmt.Errorf(\"%s: missing discriminator %%q\", %s)\n\t}\n", d.Name, strconv.Quote(d.Disc))
	g.w("\tswitch *probe.Disc {\n")
	for _, v := range d.Variants {
		g.w("\tcase %s:\n", strconv.Quote(v.Value))
		g.w("\t\tv, err := decodeStrict[%s](data)\n", v.Decl.Name)
		g.w("\t\tif err != nil {\n\t\t\treturn fmt.Errorf(\"%s: %%w\", err)\n\t\t}\n", d.Name)
		g.w("\t\tu.Value = v\n")
	}
	g.w("\tdefault:\n\t\treturn fmt.Errorf(\"%s: unknown %%s %%q\", %s, *probe.Disc)\n\t}\n", d.Name, strconv.Quote(d.Disc))
	g.w("\treturn nil\n}\n\n")
}

// goSource finishes a file: header, package clause, imports, body, gofmt.
func (g *goFile) source(schemaRel string) ([]byte, error) {
	var out strings.Builder
	fmt.Fprintf(&out, "// %s from %s. DO NOT EDIT.\n\n", generatedMarker, schemaRel)
	fmt.Fprintf(&out, "package %s\n\n", goPkgName(g.area))
	if len(g.imports) > 0 {
		var std, local []string
		for p := range g.imports {
			if strings.Contains(strings.SplitN(p, "/", 2)[0], ".") {
				local = append(local, p)
			} else {
				std = append(std, p)
			}
		}
		sort.Strings(std)
		sort.Strings(local)
		out.WriteString("import (\n")
		for _, p := range std {
			fmt.Fprintf(&out, "\t%s\n", strconv.Quote(p))
		}
		if len(std) > 0 && len(local) > 0 {
			out.WriteString("\n")
		}
		for _, p := range local {
			fmt.Fprintf(&out, "\t%s\n", strconv.Quote(p))
		}
		out.WriteString(")\n\n")
	}
	out.WriteString(g.body.String())
	src, err := format.Source([]byte(out.String()))
	if err != nil {
		return nil, fmt.Errorf("generated Go for %s does not parse: %w\n%s", schemaRel, err, numbered(out.String()))
	}
	return src, nil
}

// numbered prefixes source lines with their numbers, for error messages.
func numbered(s string) string {
	lines := strings.Split(s, "\n")
	for i := range lines {
		lines[i] = fmt.Sprintf("%4d  %s", i+1, lines[i])
	}
	return strings.Join(lines, "\n")
}

// emitGoPackageDoc renders doc.gen.go: the package comment and, when the
// package has unions, the strict decoder they share.
func emitGoPackageDoc(area string, hasUnion bool) ([]byte, error) {
	var out strings.Builder
	fmt.Fprintf(&out, "// %s. DO NOT EDIT.\n\n", generatedMarker)
	out.WriteString(goComment("", docLines(96,
		fmt.Sprintf("Package %s holds the Go types generated from the JSON Schemas in schemas/%s by tools/schemagen (go run ./tools/schemagen).", goPkgName(area), area),
		"The schemas are the contract and stay authoritative: these types express shape only. Patterns, lengths, ranges, uniqueness and cross-field rules (if/then/else) are enforced by schema validation, never by the types. Enums and union discriminators are enforced when a value is encoded or decoded; a required const member is written as its constant when encoded, and const members are checked on decode only by schema validation. Decoding a payload with json.Decoder.DisallowUnknownFields additionally enforces additionalProperties: false; union variants are always decoded that way.",
		"Optional members are pointers (or omitted when zero for slices, maps and interfaces); required nullable members encode as null when nil. Every property carries its x-alixai-authority (model, alixai or host) in the alixai struct tag.",
	)))
	fmt.Fprintf(&out, "package %s\n", goPkgName(area))
	if hasUnion {
		out.WriteString("\nimport (\n\t\"bytes\"\n\t\"encoding/json\"\n)\n\n")
		out.WriteString("// decodeStrict decodes one JSON value into T and rejects unknown members.\n")
		out.WriteString("func decodeStrict[T any](data []byte) (T, error) {\n")
		out.WriteString("\tvar v T\n\tdec := json.NewDecoder(bytes.NewReader(data))\n\tdec.DisallowUnknownFields()\n")
		out.WriteString("\tif err := dec.Decode(&v); err != nil {\n\t\tvar zero T\n\t\treturn zero, err\n\t}\n\treturn v, nil\n}\n")
	}
	src, err := format.Source([]byte(out.String()))
	if err != nil {
		return nil, fmt.Errorf("generated doc.gen.go for %s does not parse: %w", area, err)
	}
	return src, nil
}
